package com.moodtools.hub

internal object LauncherTranslationChunk1 {
    val entries = mapOf(
        "Android didn't open its installer in time. The verified download is still saved; tap Try again." to arrayOf("Hindi nabuksan ng Android ang installer sa oras. Ang naverify na download ay naka-save pa rin; pindutin ang Subukang muli.", "Android\uC774 \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8\uC744 \uC81C\uC2DC\uAC04\uC5D0 \uC5F4\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uD655\uC778\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uB294 \uC5EC\uC804\uD788 \uC800\uC7A5\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. '\uB2E4\uC2DC \uC2DC\uB3C4'\uB97C \uD0ED\uD558\uC138\uC694.", "Android\u306F\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u6642\u9593\u5185\u306B\u958B\u3051\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u78BA\u8A8D\u6E08\u307F\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u307E\u3060\u4FDD\u5B58\u3055\u308C\u3066\u3044\u307E\u3059\u3002\u300C\u518D\u8A66\u884C\u300D\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Android \u672A\u53CA\u65F6\u6253\u5F00\u5176\u5B89\u88C5\u7A0B\u5E8F\u3002\u5DF2\u4FDD\u5B58\u7ECF\u8FC7\u9A8C\u8BC1\u7684\u4E0B\u8F7D\uFF1B\u70B9\u51FB\u91CD\u8BD5\u3002", "Android no abri\u00F3 su instalador a tiempo. La descarga verificada todav\u00EDa est\u00E1 guardada; toca Intentar de nuevo.", "Android kh\u00F4ng m\u1EDF tr\u00ECnh c\u00E0i \u0111\u1EB7t k\u1ECBp th\u1EDDi. T\u1EC7p t\u1EA3i xu\u1ED1ng \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh v\u1EABn \u0111\u01B0\u1EE3c l\u01B0u; h\u00E3y nh\u1EA5n Th\u1EED l\u1EA1i.", "Android tidak membuka penginstalnya tepat waktu. Unduhan yang telah diverifikasi masih tersimpan; ketuk Coba lagi.", "O Android n\u00E3o abriu seu instalador a tempo. O download verificado ainda est\u00E1 salvo; toque em Tentar novamente."),
        "Android installed the package, but its verified package identity was not ready in time. Return to the Library and refresh before retrying." to arrayOf("Na-install ng Android ang package, pero ang naverify na pagkakakilanlan ng package ay hindi handa sa oras. Bumalik sa Library at i-refresh bago muling subukan.", "Android\uAC00 \uD328\uD0A4\uC9C0\uB97C \uC124\uCE58\uD588\uC9C0\uB9CC \uD655\uC778\uB41C \uD328\uD0A4\uC9C0 \uC2DD\uBCC4\uC774 \uC81C\uC2DC\uAC04\uC5D0 \uC900\uBE44\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uB77C\uC774\uBE0C\uB7EC\uB9AC\uB85C \uB3CC\uC544\uAC00 \uC0C8\uB85C \uACE0\uCE5C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "Android\u306F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u307E\u3057\u305F\u304C\u3001\u78BA\u8A8D\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u306E\u8B58\u5225\u304C\u6642\u9593\u5185\u306B\u6E96\u5099\u3055\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30E9\u30A4\u30D6\u30E9\u30EA\u306B\u623B\u3063\u3066\u66F4\u65B0\u3057\u3066\u304B\u3089\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Android \u5DF2\u5B89\u88C5\u8BE5\u5305\uFF0C\u4F46\u5176\u7ECF\u8FC7\u9A8C\u8BC1\u7684\u5305\u8EAB\u4EFD\u672A\u53CA\u65F6\u5C31\u7EEA\u3002\u8FD4\u56DE\u5E93\u5E76\u5237\u65B0\u540E\u518D\u91CD\u8BD5\u3002", "Android instal\u00F3 el paquete, pero la identidad del paquete verificado no estaba lista a tiempo. Vuelve a la Biblioteca y actualiza antes de intentar de nuevo.", "Android \u0111\u00E3 c\u00E0i \u0111\u1EB7t g\u00F3i, nh\u01B0ng nh\u1EADn d\u1EA1ng g\u00F3i \u0111\u00E3 x\u00E1c minh c\u1EE7a n\u00F3 ch\u01B0a s\u1EB5n s\u00E0ng k\u1ECBp l\u00FAc. Quay l\u1EA1i Th\u01B0 vi\u1EC7n v\u00E0 l\u00E0m m\u1EDBi tr\u01B0\u1EDBc khi th\u1EED l\u1EA1i.", "Android menginstal paket, tetapi identitas paket yang diverifikasi tidak siap tepat waktu. Kembali ke Perpustakaan dan segarkan sebelum mencoba lagi.", "O Android instalou o pacote, mas a identidade do pacote verificado n\u00E3o estava pronta a tempo. Volte para a Biblioteca e atualize antes de tentar novamente."),
        "Android installer closed" to arrayOf("Magsara ang Android installer", "Android \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8 \uC885\uB8CC\uB428", "Android\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u304C\u9589\u3058\u3089\u308C\u307E\u3057\u305F", "Android \u5B89\u88C5\u7A0B\u5E8F\u5DF2\u5173\u95ED", "Instalador de Android cerrado", "Tr\u00ECnh c\u00E0i \u0111\u1EB7t Android \u0111\u00E3 \u0111\u00F3ng", "Penginstal Android ditutup", "Instalador do Android fechado"),
        "Android installer did not report a result before the recovery timeout" to arrayOf("Hindi nag-ulat ang Android installer ng resulta bago sumapit ang recovery timeout", "Android \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8\uC774 \uBCF5\uAD6C \uC2DC\uAC04 \uCD08\uACFC \uC804\uC5D0 \uACB0\uACFC\uB97C \uBCF4\uACE0\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.", "Android\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u306F\u5FA9\u65E7\u30BF\u30A4\u30E0\u30A2\u30A6\u30C8\u524D\u306B\u7D50\u679C\u3092\u5831\u544A\u3057\u307E\u305B\u3093\u3067\u3057\u305F", "Android \u5B89\u88C5\u7A0B\u5E8F\u5728\u6062\u590D\u8D85\u65F6\u524D\u672A\u62A5\u544A\u7ED3\u679C", "El instalador de Android no inform\u00F3 un resultado antes de que expirara el tiempo de recuperaci\u00F3n", "Tr\u00ECnh c\u00E0i \u0111\u1EB7t Android kh\u00F4ng b\u00E1o k\u1EBFt qu\u1EA3 tr\u01B0\u1EDBc khi h\u1EBFt th\u1EDDi gian kh\u00F4i ph\u1EE5c", "Penginstal Android tidak melaporkan hasil sebelum batas waktu pemulihan", "O instalador do Android n\u00E3o informou um resultado antes do tempo limite de recupera\u00E7\u00E3o"),
        "Android installer session {0} opened" to arrayOf("Binuksan ang Android installer session {0}", "Android \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8 \uC138\uC158 {0}\uC774(\uAC00) \uC5F4\uB838\uC2B5\uB2C8\uB2E4.", "Android\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u30BB\u30C3\u30B7\u30E7\u30F3{0}\u304C\u958B\u304B\u308C\u307E\u3057\u305F", "Android \u5B89\u88C5\u7A0B\u5E8F\u4F1A\u8BDD {0} \u5DF2\u6253\u5F00", "Sesi\u00F3n del instalador de Android {0} abierta", "Phi\u00EAn tr\u00ECnh c\u00E0i \u0111\u1EB7t Android {0} \u0111\u00E3 m\u1EDF", "Sesi penginstal Android {0} dibuka", "Sess\u00E3o do instalador do Android {0} aberta"),
        "Android is preparing its confirmation screen." to arrayOf("Ang Android ay naghahanda ng screen ng kumpirmasyon nito.", "Android\uAC00 \uD655\uC778 \uD654\uBA74\uC744 \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4.", "Android\u306F\u78BA\u8A8D\u753B\u9762\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u3002", "Android \u6B63\u5728\u51C6\u5907\u5176\u786E\u8BA4\u5C4F\u5E55\u3002", "Android est\u00E1 preparando su pantalla de confirmaci\u00F3n.", "Android \u0111ang chu\u1EA9n b\u1ECB m\u00E0n h\u00ECnh x\u00E1c nh\u1EADn c\u1EE7a n\u00F3.", "Android sedang menyiapkan layar konfirmasinya.", "Android est\u00E1 preparando sua tela de confirma\u00E7\u00E3o."),
        "Android is taking longer than expected. Tap Install update to open the confirmation again." to arrayOf("Mas matagal kaysa sa inaasahan ang Android. Pindutin ang I-install ang update upang muling buksan ang kumpirmasyon.", "Android\uAC00 \uC608\uC0C1\uBCF4\uB2E4 \uC624\uB798 \uAC78\uB9AC\uACE0 \uC788\uC2B5\uB2C8\uB2E4. \uD655\uC778\uC744 \uB2E4\uC2DC \uC5F4\uB824\uBA74 \uC5C5\uB370\uC774\uD2B8 \uC124\uCE58\uB97C \uD0ED\uD558\uC138\uC694.", "Android\u306F\u4E88\u60F3\u3088\u308A\u6642\u9593\u304C\u304B\u304B\u3063\u3066\u3044\u307E\u3059\u3002\u78BA\u8A8D\u3092\u518D\u5EA6\u958B\u304F\u306B\u306F[\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB]\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Android \u8FD0\u884C\u65F6\u95F4\u6BD4\u9884\u671F\u66F4\u957F\u3002\u70B9\u51FB\u5B89\u88C5\u66F4\u65B0\u4EE5\u518D\u6B21\u6253\u5F00\u786E\u8BA4\u3002", "Android est\u00E1 tardando m\u00E1s de lo esperado. Toque Instalar actualizaci\u00F3n para abrir la confirmaci\u00F3n nuevamente.", "Android \u0111ang m\u1EA5t nhi\u1EC1u th\u1EDDi gian h\u01A1n d\u1EF1 ki\u1EBFn. Nh\u1EA5n C\u00E0i \u0111\u1EB7t b\u1EA3n c\u1EADp nh\u1EADt \u0111\u1EC3 m\u1EDF l\u1EA1i m\u00E0n h\u00ECnh x\u00E1c nh\u1EADn.", "Android memerlukan waktu lebih lama dari yang diperkirakan. Ketuk Pasang pembaruan untuk membuka konfirmasi lagi.", "Android est\u00E1 demorando mais do que o esperado. Toque em Instalar atualiza\u00E7\u00E3o para abrir novamente a confirma\u00E7\u00E3o."),
        "Android must remove the previous patched installation before an original game package can be restored. Its local app data will be erased." to arrayOf("Kailangan ng Android alisin ang nakaraang na-patch na installation bago maibalik ang orihinal na package ng laro. Mabubura ang lokal na data ng app nito.", "Android\uB294 \uC6D0\uBCF8 \uAC8C\uC784 \uD328\uD0A4\uC9C0\uB97C \uBCF5\uC6D0\uD558\uAE30 \uC804\uC5D0 \uC774\uC804 \uD328\uCE58 \uC124\uCE58\uB97C \uC81C\uAC70\uD574\uC57C \uD569\uB2C8\uB2E4. \uB85C\uCEEC \uC571 \uB370\uC774\uD130\uAC00 \uC0AD\uC81C\uB429\uB2C8\uB2E4.", "Android\u306F\u4EE5\u524D\u306E\u30D1\u30C3\u30C1\u6E08\u307F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u524A\u9664\u3059\u308B\u5FC5\u8981\u304C\u3042\u308A\u307E\u3059\u3002\u5143\u306E\u30B2\u30FC\u30E0\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u5FA9\u5143\u3059\u308B\u524D\u306B\u3001\u30ED\u30FC\u30AB\u30EB\u30A2\u30D7\u30EA\u30C7\u30FC\u30BF\u306F\u6D88\u53BB\u3055\u308C\u307E\u3059\u3002", "\u5728\u6062\u590D\u539F\u59CB\u6E38\u620F\u5305\u4E4B\u524D\uFF0CAndroid \u5FC5\u987B\u79FB\u9664\u4E4B\u524D\u7684\u8865\u4E01\u5B89\u88C5\u3002\u5176\u672C\u5730\u5E94\u7528\u6570\u636E\u5C06\u88AB\u6E05\u9664\u3002", "Android debe eliminar la instalaci\u00F3n parcheada anterior antes de que pueda restaurarse un paquete de juego original. Sus datos locales de la aplicaci\u00F3n ser\u00E1n borrados.", "Android ph\u1EA3i g\u1EE1 b\u1ECF c\u00E0i \u0111\u1EB7t b\u1EA3n v\u00E1 tr\u01B0\u1EDBc \u0111\u00F3 tr\u01B0\u1EDBc khi c\u00F3 th\u1EC3 kh\u00F4i ph\u1EE5c g\u00F3i tr\u00F2 ch\u01A1i g\u1ED1c. D\u1EEF li\u1EC7u \u1EE9ng d\u1EE5ng c\u1EE5c b\u1ED9 c\u1EE7a n\u00F3 s\u1EBD b\u1ECB x\u00F3a.", "Android harus menghapus instalasi yang sudah dipatch sebelumnya sebelum paket game asli dapat dipulihkan. Data aplikasi lokalnya akan dihapus.", "O Android deve remover a instala\u00E7\u00E3o anterior corrigida antes que um pacote de jogo original possa ser restaurado. Seus dados locais do aplicativo ser\u00E3o apagados."),
        "Android package confirmation opened" to arrayOf("Nabuksan ang kumpirmasyon ng package ng Android", "Android \uD328\uD0A4\uC9C0 \uD655\uC778\uC774 \uC5F4\uB838\uC2B5\uB2C8\uB2E4.", "Android\u30D1\u30C3\u30B1\u30FC\u30B8\u78BA\u8A8D\u304C\u958B\u304B\u308C\u307E\u3057\u305F", "Android \u5305\u786E\u8BA4\u5DF2\u6253\u5F00", "Confirmaci\u00F3n del paquete de Android abierta", "M\u00E0n h\u00ECnh x\u00E1c nh\u1EADn g\u00F3i Android \u0111\u00E3 \u0111\u01B0\u1EE3c m\u1EDF", "Konfirmasi paket Android dibuka", "Confirma\u00E7\u00E3o do pacote Android aberta"),
        "Android returned without installing the target build" to arrayOf("Binalik ng Android nang hindi ini-install ang target na build", "Android\uAC00 \uB300\uC0C1 \uBE4C\uB4DC\uB97C \uC124\uCE58\uD558\uC9C0 \uC54A\uACE0 \uB3CC\uC544\uC654\uC2B5\uB2C8\uB2E4.", "Android\u306F\u30BF\u30FC\u30B2\u30C3\u30C8\u30D3\u30EB\u30C9\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u305B\u305A\u306B\u623B\u308A\u307E\u3057\u305F", "Android \u8FD4\u56DE\u4F46\u672A\u5B89\u88C5\u76EE\u6807\u7248\u672C", "Android regres\u00F3 sin instalar la compilaci\u00F3n objetivo", "Android \u0111\u00E3 quay l\u1EA1i m\u00E0 kh\u00F4ng c\u00E0i \u0111\u1EB7t b\u1EA3n d\u1EF1ng m\u1EE5c ti\u00EAu", "Android kembali tanpa memasang build target", "Android retornou sem instalar a compila\u00E7\u00E3o alvo"),
        "Any game you already have open will keep running." to arrayOf("Patuloy pa rin ang anumang laro na bukas na.", "\uC774\uBBF8 \uC5F4\uC5B4\uB454 \uBAA8\uB4E0 \uAC8C\uC784\uC740 \uACC4\uC18D \uC2E4\uD589\uB429\uB2C8\uB2E4.", "\u65E2\u306B\u958B\u3044\u3066\u3044\u308B\u30B2\u30FC\u30E0\u306F\u305D\u306E\u307E\u307E\u5B9F\u884C\u3055\u308C\u307E\u3059\u3002", "\u60A8\u5DF2\u7ECF\u6253\u5F00\u7684\u4EFB\u4F55\u6E38\u620F\u5C06\u7EE7\u7EED\u8FD0\u884C\u3002", "Cualquier juego que ya tenga abierto seguir\u00E1 ejecut\u00E1ndose.", "B\u1EA5t k\u1EF3 tr\u00F2 ch\u01A1i n\u00E0o b\u1EA1n \u0111\u00E3 m\u1EDF s\u1EBD ti\u1EBFp t\u1EE5c ch\u1EA1y.", "Game apa pun yang sudah Anda buka akan tetap berjalan.", "Qualquer jogo que voc\u00EA j\u00E1 tenha aberto continuar\u00E1 rodando."),
        "Authorizing signed release" to arrayOf("Ina-awtorisa ang nilagda na release", "\uC11C\uBA85\uB41C \uB9B4\uB9AC\uC2A4\uB97C \uC2B9\uC778 \uC911\uC785\uB2C8\uB2E4.", "\u7F72\u540D\u6E08\u307F\u30EA\u30EA\u30FC\u30B9\u306E\u8A8D\u53EF\u4E2D", "\u6388\u6743\u5DF2\u7B7E\u540D\u7684\u53D1\u5E03\u7248", "Autorizando la versi\u00F3n firmada", "\u0110ang c\u1EA5p quy\u1EC1n ph\u00E1t h\u00E0nh \u0111\u00E3 k\u00FD", "Mengotorisasi rilis yang ditandatangani", "Autorizando lan\u00E7amento assinado"),
        "Authorizing the signed package for this device." to arrayOf("Ina-awtorisa ang nilagda na package para sa aparatong ito.", "\uC774 \uAE30\uAE30\uC5D0 \uB300\uD55C \uC11C\uBA85 \uD328\uD0A4\uC9C0\uB97C \uC2B9\uC778 \uC911\uC785\uB2C8\uB2E4.", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u7528\u306E\u7F72\u540D\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u8A8D\u53EF\u4E2D\u3067\u3059\u3002", "\u4E3A\u6B64\u8BBE\u5907\u6388\u6743\u5DF2\u7B7E\u540D\u7684\u8F6F\u4EF6\u5305\u3002", "Autorizando el paquete firmado para este dispositivo.", "\u0110ang c\u1EA5p quy\u1EC1n cho g\u00F3i \u0111\u00E3 k\u00FD cho thi\u1EBFt b\u1ECB n\u00E0y.", "Mengotorisasi paket yang ditandatangani untuk perangkat ini.", "Autorizando o pacote assinado para este dispositivo."),
        "Back up anything important" to arrayOf("I-back up ang anumang mahalaga", "\uC911\uC694\uD55C \uB0B4\uC6A9\uC744 \uBC31\uC5C5\uD558\uC138\uC694.", "\u91CD\u8981\u306A\u3082\u306E\u3092\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044", "\u5907\u4EFD\u4EFB\u4F55\u91CD\u8981\u5185\u5BB9", "Haga una copia de seguridad de cualquier cosa importante", "Sao l\u01B0u b\u1EA5t c\u1EE9 th\u1EE9 g\u00EC quan tr\u1ECDng", "Cadangkan hal-hal penting", "Fa\u00E7a backup de qualquer coisa importante"),
        "Building a trusted installation request for Android." to arrayOf("Gumagawa ng kahilingan para sa pinagkakatiwalaang installation para sa Android.", "Android\uC6A9 \uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uC124\uCE58 \uC694\uCCAD\uC744 \uC0DD\uC131 \uC911\uC785\uB2C8\uB2E4.", "Android\u7528\u306E\u4FE1\u983C\u3067\u304D\u308B\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u30EA\u30AF\u30A8\u30B9\u30C8\u3092\u4F5C\u6210\u3057\u3066\u3044\u307E\u3059\u3002", "\u4E3A Android \u6784\u5EFA\u53D7\u4FE1\u4EFB\u7684\u5B89\u88C5\u8BF7\u6C42\u3002", "Construyendo una solicitud de instalaci\u00F3n confiable para Android.", "\u0110ang x\u00E2y d\u1EF1ng y\u00EAu c\u1EA7u c\u00E0i \u0111\u1EB7t \u0111\u00E1ng tin c\u1EADy cho Android.", "Membangun permintaan instalasi tepercaya untuk Android.", "Construindo uma solicita\u00E7\u00E3o de instala\u00E7\u00E3o confi\u00E1vel para Android."),
        "Cancellation requested by the user" to arrayOf("Kanselasyon na hiniling ng gumagamit", "\uC0AC\uC6A9\uC790\uAC00 \uCDE8\uC18C \uC694\uCCAD\uD568", "\u30E6\u30FC\u30B6\u30FC\u306B\u3088\u308B\u30AD\u30E3\u30F3\u30BB\u30EB\u30EA\u30AF\u30A8\u30B9\u30C8", "\u7528\u6237\u8BF7\u6C42\u53D6\u6D88", "Cancelaci\u00F3n solicitada por el usuario", "H\u1EE7y b\u1ECF theo y\u00EAu c\u1EA7u c\u1EE7a ng\u01B0\u1EDDi d\u00F9ng", "Pembatalan diminta oleh pengguna", "Cancelamento solicitado pelo usu\u00E1rio"),
        "Cancelled by the user" to arrayOf("Kinansela ng gumagamit", "\uC0AC\uC6A9\uC790\uAC00 \uCDE8\uC18C\uD588\uC2B5\uB2C8\uB2E4.", "\u30E6\u30FC\u30B6\u30FC\u306B\u3088\u3063\u3066\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F", "\u5DF2\u88AB\u7528\u6237\u53D6\u6D88", "Cancelado por el usuario", "B\u1ECB h\u1EE7y b\u1ECF b\u1EDFi ng\u01B0\u1EDDi d\u00F9ng", "Dibatalkan oleh pengguna", "Cancelado pelo usu\u00E1rio"),
        "Catalog refresh failed" to arrayOf("Nabigong i-refresh ang katalogo", "\uCE74\uD0C8\uB85C\uADF8 \uC0C8\uB85C \uACE0\uCE68 \uC2E4\uD328", "\u30AB\u30BF\u30ED\u30B0\u306E\u66F4\u65B0\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u76EE\u5F55\u5237\u65B0\u5931\u8D25", "Fallo al actualizar el cat\u00E1logo", "L\u00E0m m\u1EDBi danh m\u1EE5c th\u1EA5t b\u1EA1i", "Penyegaran katalog gagal", "Falha ao atualizar o cat\u00E1logo"),
        "Catalog refreshed" to arrayOf("Na-refresh ang katalogo", "\uCE74\uD0C8\uB85C\uADF8 \uC0C8\uB85C \uACE0\uCE68", "\u30AB\u30BF\u30ED\u30B0\u3092\u66F4\u65B0\u3057\u307E\u3057\u305F", "\u76EE\u5F55\u5DF2\u5237\u65B0", "Cat\u00E1logo actualizado", "Danh m\u1EE5c \u0111\u00E3 \u0111\u01B0\u1EE3c l\u00E0m m\u1EDBi", "Katalog disegarkan", "Cat\u00E1logo atualizado"),
        "Check the helper output, then try again." to arrayOf("Suriin ang output ng helper, pagkatapos subukang muli.", "\uB3C4\uC6B0\uBBF8 \uCD9C\uB825\uC744 \uD655\uC778\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "\u30D8\u30EB\u30D1\u30FC\u306E\u51FA\u529B\u3092\u78BA\u8A8D\u3057\u3066\u304B\u3089\u3001\u3082\u3046\u4E00\u5EA6\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u68C0\u67E5\u52A9\u624B\u8F93\u51FA\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Verifica la salida del asistente, luego int\u00E9ntalo de nuevo.", "Ki\u1EC3m tra k\u1EBFt qu\u1EA3 tr\u1EE3 gi\u00FAp, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Periksa output pembantu, lalu coba lagi.", "Verifique a sa\u00EDda do assistente e tente novamente."),
        "Check your connection, then try again. Any game already open will keep running." to arrayOf("Suriin ang iyong koneksyon, pagkatapos subukang muli. Anumang laro na nakabukas na ay magpapatuloy sa pagpapatakbo.", "\uC5F0\uACB0\uC744 \uD655\uC778\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694. \uC774\uBBF8 \uC5F4\uB824 \uC788\uB294 \uAC8C\uC784\uC740 \uACC4\uC18D \uC2E4\uD589\uB429\uB2C8\uB2E4.", "\u63A5\u7D9A\u3092\u78BA\u8A8D\u3057\u3066\u304B\u3089\u3001\u3082\u3046\u4E00\u5EA6\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u3059\u3067\u306B\u958B\u3044\u3066\u3044\u308B\u30B2\u30FC\u30E0\u306F\u305D\u306E\u307E\u307E\u5B9F\u884C\u3055\u308C\u307E\u3059\u3002", "\u68C0\u67E5\u60A8\u7684\u8FDE\u63A5\uFF0C\u7136\u540E\u91CD\u8BD5\u3002\u4EFB\u4F55\u5DF2\u6253\u5F00\u7684\u6E38\u620F\u5C06\u7EE7\u7EED\u8FD0\u884C\u3002", "Verifica tu conexi\u00F3n, luego int\u00E9ntalo de nuevo. Cualquier juego ya abierto continuar\u00E1 ejecut\u00E1ndose.", "Ki\u1EC3m tra k\u1EBFt n\u1ED1i c\u1EE7a b\u1EA1n, sau \u0111\u00F3 th\u1EED l\u1EA1i. B\u1EA5t k\u1EF3 tr\u00F2 ch\u01A1i n\u00E0o \u0111\u00E3 m\u1EDF s\u1EBD ti\u1EBFp t\u1EE5c ch\u1EA1y.", "Periksa koneksi Anda, lalu coba lagi. Game yang sudah terbuka akan tetap berjalan.", "Verifique sua conex\u00E3o e tente novamente. Qualquer jogo j\u00E1 aberto continuar\u00E1 em execu\u00E7\u00E3o."),
        "Checking access" to arrayOf("Sinusuri ang access", "\uC811\uADFC \uD655\uC778 \uC911", "\u30A2\u30AF\u30BB\u30B9\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u68C0\u67E5\u8BBF\u95EE\u6743\u9650", "Comprobando acceso", "\u0110ang ki\u1EC3m tra quy\u1EC1n truy c\u1EADp", "Memeriksa akses", "Verificando acesso"),
        "Checking for a reusable verified package first." to arrayOf("Sinusuri muna ang reusable verified package.", "\uBA3C\uC800 \uC7AC\uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uAC80\uC99D\uB41C \uD328\uD0A4\uC9C0 \uD655\uC778 \uC911.", "\u307E\u305A\u518D\u5229\u7528\u53EF\u80FD\u306A\u691C\u8A3C\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u78BA\u8A8D\u4E2D", "\u9996\u5148\u68C0\u67E5\u53EF\u91CD\u590D\u4F7F\u7528\u7684\u5DF2\u9A8C\u8BC1\u5305\u3002", "Comprobando primero si hay un paquete verificado reutilizable.", "Tr\u01B0\u1EDBc ti\u00EAn ki\u1EC3m tra g\u00F3i \u0111\u00E3 x\u00E1c minh c\u00F3 th\u1EC3 t\u00E1i s\u1EED d\u1EE5ng.", "Memeriksa paket terverifikasi yang dapat digunakan kembali terlebih dahulu.", "Verificando primeiro por um pacote verificado reutiliz\u00E1vel."),
        "Checking for updates" to arrayOf("Sinusuri para sa mga update", "\uC5C5\uB370\uC774\uD2B8 \uD655\uC778 \uC911", "\u66F4\u65B0\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u68C0\u67E5\u66F4\u65B0", "Buscando actualizaciones", "\u0110ang ki\u1EC3m tra c\u1EADp nh\u1EADt", "Memeriksa pembaruan", "Verificando atualiza\u00E7\u00F5es"),
        "Checking integrity, app identity, and signing certificate." to arrayOf("Sinusuri ang integridad, pagkakakilanlan ng app, at signing certificate.", "\uBB34\uACB0\uC131, \uC571 \uC544\uC774\uB374\uD2F0\uD2F0, \uC11C\uBA85 \uC778\uC99D\uC11C \uD655\uC778 \uC911.", "\u5B8C\u5168\u6027\u3001\u30A2\u30D7\u30EA\u306E\u8B58\u5225\u3001\u304A\u3088\u3073\u7F72\u540D\u8A3C\u660E\u66F8\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u68C0\u67E5\u5B8C\u6574\u6027\u3001\u5E94\u7528\u8EAB\u4EFD\u548C\u7B7E\u540D\u8BC1\u4E66\u3002", "Verificando la integridad, identidad de la aplicaci\u00F3n y certificado de firma.", "\u0110ang ki\u1EC3m tra t\u00EDnh to\u00E0n v\u1EB9n, nh\u1EADn d\u1EA1ng \u1EE9ng d\u1EE5ng v\u00E0 ch\u1EE9ng ch\u1EC9 k\u00FD.", "Memeriksa integritas, identitas aplikasi, dan sertifikat penandatanganan.", "Verificando integridade, identidade do aplicativo e certificado de assinatura."),
        "Checking saved launcher update" to arrayOf("Sinusuri ang na-save na launcher update", "\uC800\uC7A5\uB41C \uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uD655\uC778 \uC911", "\u4FDD\u5B58\u3055\u308C\u305F\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u68C0\u67E5\u5DF2\u4FDD\u5B58\u7684\u542F\u52A8\u5668\u66F4\u65B0", "Comprobando actualizaci\u00F3n guardada del lanzador", "\u0110ang ki\u1EC3m tra c\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y \u0111\u00E3 l\u01B0u", "Memeriksa pembaruan peluncur yang tersimpan", "Verificando atualiza\u00E7\u00E3o do inicializador salva"),
        "Checking saved package" to arrayOf("Sinusuri ang na-save na package", "\uC800\uC7A5\uB41C \uD328\uD0A4\uC9C0 \uD655\uC778 \uC911", "\u4FDD\u5B58\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u68C0\u67E5\u5DF2\u4FDD\u5B58\u7684\u5305", "Comprobando paquete guardado", "\u0110ang ki\u1EC3m tra g\u00F3i \u0111\u00E3 l\u01B0u", "Memeriksa paket yang tersimpan", "Verificando pacote salvo"),
        "Checking the download for {0}." to arrayOf("Sinusuri ang download para sa {0}.", "{0} \uB2E4\uC6B4\uB85C\uB4DC \uD655\uC778 \uC911.", "{0} \u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u68C0\u67E5 {0} \u7684\u4E0B\u8F7D\u5185\u5BB9\u3002", "Comprobando la descarga de {0}.", "\u0110ang ki\u1EC3m tra t\u1EA3i xu\u1ED1ng cho {0}.", "Memeriksa unduhan untuk {0}.", "Verificando o download de {0}."),
        "Checking the files for {0}." to arrayOf("Sinusuri ang mga file para sa {0}.", "{0} \uD30C\uC77C \uD655\uC778 \uC911.", "{0} \u306E\u30D5\u30A1\u30A4\u30EB\u3092\u78BA\u8A8D\u4E2D", "\u6B63\u5728\u68C0\u67E5 {0} \u7684\u6587\u4EF6\u3002", "Comprobando los archivos de {0}.", "\u0110ang ki\u1EC3m tra c\u00E1c t\u1EC7p cho {0}.", "Memeriksa file untuk {0}.", "Verificando os arquivos de {0}."),
        "Checking the signed package before anything is handed to Android." to arrayOf("Sinusuri ang signed package bago ihatid sa Android.", "Android\uC5D0 \uC804\uB2EC\uD558\uAE30 \uC804\uC5D0 \uC11C\uBA85\uB41C \uD328\uD0A4\uC9C0 \uD655\uC778 \uC911.", "Android \u306B\u4F55\u3082\u6E21\u3059\u524D\u306B\u7F72\u540D\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u78BA\u8A8D\u4E2D", "\u5728\u5C06\u4EFB\u4F55\u5185\u5BB9\u4EA4\u7ED9 Android \u4E4B\u524D\u68C0\u67E5\u5DF2\u7B7E\u540D\u5305\u3002", "Comprobando el paquete firmado antes de entregarlo a Android.", "\u0110ang ki\u1EC3m tra g\u00F3i \u0111\u00E3 k\u00FD tr\u01B0\u1EDBc khi b\u1EA5t c\u1EE9 th\u1EE9 g\u00EC \u0111\u01B0\u1EE3c chuy\u1EC3n cho Android.", "Memeriksa paket yang ditandatangani sebelum menyerahkannya ke Android.", "Verificando o pacote assinado antes de entregar qualquer coisa ao Android."),
        "Choose the original game source" to arrayOf("Piliin ang orihinal na pinagmulan ng laro", "\uC6D0\uBCF8 \uAC8C\uC784 \uC18C\uC2A4 \uC120\uD0DD", "\u5143\u306E\u30B2\u30FC\u30E0\u30BD\u30FC\u30B9\u3092\u9078\u629E", "\u9009\u62E9\u539F\u59CB\u6E38\u620F\u6765\u6E90", "Elige la fuente de juego original", "Ch\u1ECDn ngu\u1ED3n tr\u00F2 ch\u01A1i g\u1ED1c", "Pilih sumber game asli", "Escolha a fonte original do jogo"),
        "Clear {0} data?" to arrayOf("I-clear ang {0} data?", "{0} \uB370\uC774\uD130\uB97C \uC9C0\uC6B0\uC2DC\uACA0\uC2B5\uB2C8\uAE4C?", "{0} \u306E\u30C7\u30FC\u30BF\u3092\u6D88\u53BB\u3057\u307E\u3059\u304B\uFF1F", "\u6E05\u9664 {0} \u6570\u636E\uFF1F", "\u00BFBorrar datos de {0}?", "X\u00F3a d\u1EEF li\u1EC7u {0}?", "Hapus data {0}?", "Limpar dados de {0}?"),
        "Clearing game data" to arrayOf("I-clear ang data ng laro", "\uAC8C\uC784 \uB370\uC774\uD130 \uC0AD\uC81C \uC911", "\u30B2\u30FC\u30E0\u30C7\u30FC\u30BF\u3092\u6D88\u53BB\u4E2D", "\u6B63\u5728\u6E05\u9664\u6E38\u620F\u6570\u636E", "Borrando datos del juego", "\u0110ang x\u00F3a d\u1EEF li\u1EC7u tr\u00F2 ch\u01A1i", "Menghapus data game", "Limpando dados do jogo"),
        "Clearing managed game data" to arrayOf("I-clear ang managed game data", "\uAD00\uB9AC\uB418\uB294 \uAC8C\uC784 \uB370\uC774\uD130 \uC0AD\uC81C \uC911", "\u7BA1\u7406\u3055\u308C\u305F\u30B2\u30FC\u30E0\u30C7\u30FC\u30BF\u3092\u6D88\u53BB\u4E2D", "\u6B63\u5728\u6E05\u9664\u7BA1\u7406\u7684\u6E38\u620F\u6570\u636E", "Borrando datos del juego gestionados", "\u0110ang x\u00F3a d\u1EEF li\u1EC7u tr\u00F2 ch\u01A1i \u0111\u01B0\u1EE3c qu\u1EA3n l\u00FD", "Menghapus data game yang dikelola", "Limpando dados do jogo gerenciados"),
        "Comparing your installed version with the latest available version." to arrayOf("Paghahambing ng iyong naka-install na bersyon sa pinakabagong bersyon na magagamit.", "\uC124\uCE58\uB41C \uBC84\uC804\uC744 \uCD5C\uC2E0 \uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uBC84\uC804\uACFC \uBE44\uAD50\uD569\uB2C8\uB2E4.", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u308B\u30D0\u30FC\u30B8\u30E7\u30F3\u3092\u3001\u5229\u7528\u53EF\u80FD\u306A\u6700\u65B0\u30D0\u30FC\u30B8\u30E7\u30F3\u3068\u6BD4\u8F03\u3057\u3066\u3044\u307E\u3059\u3002", "\u5C06\u60A8\u5DF2\u5B89\u88C5\u7684\u7248\u672C\u4E0E\u6700\u65B0\u53EF\u7528\u7248\u672C\u8FDB\u884C\u6BD4\u8F83\u3002", "Comparando tu versi\u00F3n instalada con la \u00FAltima versi\u00F3n disponible.", "So s\u00E1nh phi\u00EAn b\u1EA3n b\u1EA1n \u0111\u00E3 c\u00E0i \u0111\u1EB7t v\u1EDBi phi\u00EAn b\u1EA3n m\u1EDBi nh\u1EA5t c\u00F3 s\u1EB5n.", "Membandingkan versi yang Anda pasang dengan versi terbaru yang tersedia.", "Comparando sua vers\u00E3o instalada com a vers\u00E3o mais recente dispon\u00EDvel."),
        "Complete the quick verification, then Jester Mods will finish the update." to arrayOf("Kumpletuhin ang mabilisang beripikasyon, pagkatapos ay tatapusin ng Jester Mods ang pag-update.", "\uBE60\uB978 \uD655\uC778\uC744 \uC644\uB8CC\uD55C \uD6C4 Jester Mods\uAC00 \uC5C5\uB370\uC774\uD2B8\uB97C \uC644\uB8CC\uD569\uB2C8\uB2E4.", "\u30AF\u30A4\u30C3\u30AF\u78BA\u8A8D\u3092\u5B8C\u4E86\u3059\u308B\u3068\u3001Jester Mods \u304C\u66F4\u65B0\u3092\u5B8C\u4E86\u3057\u307E\u3059\u3002", "\u5B8C\u6210\u5FEB\u901F\u9A8C\u8BC1\uFF0C\u7136\u540E Jester Mods \u5C06\u5B8C\u6210\u66F4\u65B0\u3002", "Completa la verificaci\u00F3n r\u00E1pida, luego Jester Mods finalizar\u00E1 la actualizaci\u00F3n.", "Ho\u00E0n t\u1EA5t vi\u1EC7c ki\u1EC3m tra nhanh, sau \u0111\u00F3 Jester Mods s\u1EBD ho\u00E0n t\u1EA5t vi\u1EC7c c\u1EADp nh\u1EADt.", "Selesaikan verifikasi cepat, kemudian Jester Mods akan menyelesaikan pembaruan.", "Complete a verifica\u00E7\u00E3o r\u00E1pida, ent\u00E3o o Jester Mods finalizar\u00E1 a atualiza\u00E7\u00E3o."),
        "Confirm the game-branded shell installation. The launcher will detect when it finishes." to arrayOf("Kumpirmahin ang pag-install ng game-branded shell. Makikita nito ang pagtatapos kapag natapos na.", "\uAC8C\uC784 \uBE0C\uB79C\uB529 \uC178 \uC124\uCE58\uB97C \uD655\uC778\uD569\uB2C8\uB2E4. \uB7F0\uCC98\uAC00 \uC644\uB8CC\uB418\uBA74 \uAC10\uC9C0\uD569\uB2C8\uB2E4.", "\u30B2\u30FC\u30E0\u30D6\u30E9\u30F3\u30C9\u306E\u30B7\u30A7\u30EB\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u5B8C\u4E86\u3059\u308B\u3068\u30E9\u30F3\u30C1\u30E3\u30FC\u304C\u691C\u51FA\u3057\u307E\u3059\u3002", "\u786E\u8BA4\u6E38\u620F\u54C1\u724C\u5916\u58F3\u7684\u5B89\u88C5\u3002\u542F\u52A8\u5668\u5C06\u5728\u5B8C\u6210\u65F6\u68C0\u6D4B\u5230\u3002", "Confirma la instalaci\u00F3n de la versi\u00F3n oficial del juego. El lanzador detectar\u00E1 cuando termine.", "X\u00E1c nh\u1EADn c\u00E0i \u0111\u1EB7t phi\u00EAn b\u1EA3n tr\u00F2 ch\u01A1i ch\u00EDnh th\u1EE9c. Tr\u00ECnh kh\u1EDFi ch\u1EA1y s\u1EBD ph\u00E1t hi\u1EC7n khi vi\u1EC7c c\u00E0i \u0111\u1EB7t ho\u00E0n t\u1EA5t.", "Konfirmasi pemasangan shell bersertifikat game. Peluncur akan mendeteksi saat proses selesai.", "Confirme a instala\u00E7\u00E3o do shell com marca do jogo. O launcher detectar\u00E1 quando for conclu\u00EDda."),
        "Confirm the original game installation in Android's secure prompt." to arrayOf("Kumpirmahin ang orihinal na pag-install ng laro sa secure prompt ng Android.", "Android \uBCF4\uC548 \uD504\uB86C\uD504\uD2B8\uC5D0\uC11C \uC6D0\uBCF8 \uAC8C\uC784 \uC124\uCE58\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "Android \u306E\u30BB\u30AD\u30E5\u30A2\u30D7\u30ED\u30F3\u30D7\u30C8\u3067\u5143\u306E\u30B2\u30FC\u30E0\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5728 Android \u5B89\u5168\u63D0\u793A\u4E2D\u786E\u8BA4\u539F\u59CB\u6E38\u620F\u7684\u5B89\u88C5\u3002", "Confirma la instalaci\u00F3n original del juego en el aviso seguro de Android.", "X\u00E1c nh\u1EADn c\u00E0i \u0111\u1EB7t tr\u00F2 ch\u01A1i g\u1ED1c trong l\u1EDDi nh\u1EAFc b\u1EA3o m\u1EADt c\u1EE7a Android.", "Konfirmasi pemasangan game asli di prompt aman Android.", "Confirme a instala\u00E7\u00E3o original do jogo no prompt seguro do Android."),
        "Confirm the patched game installation. The launcher will detect when it finishes." to arrayOf("Kumpirmahin ang patched na pag-install ng laro. Makikita ng launcher kapag natapos na.", "\uD328\uCE58\uB41C \uAC8C\uC784 \uC124\uCE58\uB97C \uD655\uC778\uD569\uB2C8\uB2E4. \uB7F0\uCC98\uAC00 \uC644\uB8CC\uB418\uBA74 \uAC10\uC9C0\uD569\uB2C8\uB2E4.", "\u30D1\u30C3\u30C1\u304C\u9069\u7528\u3055\u308C\u305F\u30B2\u30FC\u30E0\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u5B8C\u4E86\u3059\u308B\u3068\u30E9\u30F3\u30C1\u30E3\u30FC\u304C\u691C\u51FA\u3057\u307E\u3059\u3002", "\u786E\u8BA4\u8865\u4E01\u540E\u7684\u6E38\u620F\u5B89\u88C5\u3002\u542F\u52A8\u5668\u5C06\u5728\u5B8C\u6210\u65F6\u68C0\u6D4B\u5230\u3002", "Confirma la instalaci\u00F3n del juego parcheado. El lanzador detectar\u00E1 cuando termine.", "X\u00E1c nh\u1EADn c\u00E0i \u0111\u1EB7t tr\u00F2 ch\u01A1i \u0111\u00E3 \u0111\u01B0\u1EE3c v\u00E1. Tr\u00ECnh kh\u1EDFi ch\u1EA1y s\u1EBD ph\u00E1t hi\u1EC7n khi vi\u1EC7c c\u00E0i \u0111\u1EB7t ho\u00E0n t\u1EA5t.", "Konfirmasi pemasangan game yang telah dipatch. Peluncur akan mendeteksi saat proses selesai.", "Confirme a instala\u00E7\u00E3o do jogo corrigido. O launcher detectar\u00E1 quando for conclu\u00EDda."),
        "Confirm the patched {0} update." to arrayOf("Kumpirmahin ang patched na {0} update.", "\uD328\uCE58\uB41C {0} \uC5C5\uB370\uC774\uD2B8\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "\u30D1\u30C3\u30C1\u3055\u308C\u305F {0} \u306E\u66F4\u65B0\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u786E\u8BA4\u8865\u4E01\u540E\u7684 {0} \u66F4\u65B0\u3002", "Confirma la actualizaci\u00F3n parcheada {0}.", "X\u00E1c nh\u1EADn b\u1EA3n c\u1EADp nh\u1EADt {0} \u0111\u00E3 \u0111\u01B0\u1EE3c v\u00E1.", "Konfirmasi pembaruan {0} yang telah dipatch.", "Confirme a atualiza\u00E7\u00E3o corrigida {0}."),
    )
}
